// --- CONSTANTS & DATA ---
        // Standard Credit Card Width in mm = 85.60mm
        const CARD_WIDTH_MM = 85.60;
        // Ring Size Data (Diameter mm -> US, UK, EU, JP)
        const ringData = [
            { d: 14.0, us: "3", uk: "F", eu: "44", jp: "4" },
            { d: 14.4, us: "3.5", uk: "G", eu: "45", jp: "5" },
            { d: 14.8, us: "4", uk: "H", eu: "46.5", jp: "7" },
            { d: 15.2, us: "4.5", uk: "I", eu: "48", jp: "8" },
            { d: 15.6, us: "5", uk: "J ½", eu: "49", jp: "9" },
            { d: 16.0, us: "5.5", uk: "L", eu: "50", jp: "10" },
            { d: 16.5, us: "6", uk: "M", eu: "52", jp: "12" },
            { d: 16.9, us: "6.5", uk: "N", eu: "53", jp: "13" },
            { d: 17.3, us: "7", uk: "O", eu: "54.5", jp: "14" },
            { d: 17.7, us: "7.5", uk: "P", eu: "56", jp: "15" },
            { d: 18.2, us: "8", uk: "Q", eu: "57", jp: "16" },
            { d: 18.6, us: "8.5", uk: "Q ½", eu: "58.5", jp: "17" },
            { d: 19.0, us: "9", uk: "R ½", eu: "59.5", jp: "18" },
            { d: 19.4, us: "9.5", uk: "S ½", eu: "61", jp: "19" },
            { d: 19.8, us: "10", uk: "T ½", eu: "62", jp: "20" },
            { d: 20.2, us: "10.5", uk: "U ½", eu: "63.5", jp: "22" },
            { d: 20.6, us: "11", uk: "V ½", eu: "65", jp: "23" },
            { d: 21.0, us: "11.5", uk: "W ½", eu: "66", jp: "24" },
            { d: 21.4, us: "12", uk: "Y", eu: "67.5", jp: "25" },
            { d: 21.8, us: "12.5", uk: "Z", eu: "69", jp: "26" },
            { d: 22.2, us: "13", uk: "Z+1", eu: "70", jp: "27" }
        ];
        // --- STATE ---
        let pixelsPerMm = 3.78; // Default approx for 96DPI (1 inch = 25.4mm, 96/25.4)
        // --- LOGIC ---
        function init() {
            // Check if user has calibrated before
            const savedPPM = localStorage.getItem('ring_tool_ppm');
            if (savedPPM) {
                pixelsPerMm = parseFloat(savedPPM);
                document.getElementById('ppi-debug').innerText = "Calibrated";
            }
            updateCircleFromSlider();
        }
        function updateCircleFromSlider() {
            const sliderVal = document.getElementById('ring-slider').value;
            // Slider value 100-300 represents arbitrary range to cover roughly 13mm to 24mm
            // Let's map slider directly to diameter in mm for easier logic, then convert to px
            // Mapping 100 -> 13mm, 300 -> 24mm
            const minMm = 13;
            const maxMm = 24;
            const percent = (sliderVal - 100) / 200;
            const currentDiameterMm = minMm + (percent * (maxMm - minMm));
            // Render Visuals
            const diameterPx = currentDiameterMm * pixelsPerMm;
            const circle = document.getElementById('measurement-circle');
            circle.style.width = `${diameterPx}px`;
            circle.style.height = `${diameterPx}px`;
            document.getElementById('diameter-readout').innerText = currentDiameterMm.toFixed(2) + " mm";
            // Find closest size
            findClosestSize(currentDiameterMm);
        }
        function findClosestSize(mm) {
            // Find the closest object in ringData
            let closest = ringData.reduce((prev, curr) => {
                return (Math.abs(curr.d - mm) < Math.abs(prev.d - mm) ? curr : prev);
            });
            document.getElementById('size-us').innerText = closest.us;
            document.getElementById('size-uk').innerText = closest.uk;
            document.getElementById('size-eu').innerText = closest.eu;
            document.getElementById('size-jp').innerText = closest.jp;
        }
        // --- CALIBRATION ---
        function toggleCalibration() {
            const overlay = document.getElementById('calibration-overlay');
            overlay.classList.toggle('hidden');
            if (!overlay.classList.contains('hidden')) {
                // Reset calibration slider to current PPM state visual
                // Card width is fixed 85.6mm. 
                // Slider controls width in PX of the div. 
                // Default width of div in CSS is arbitrary, we need to set it.
                const cardDiv = document.getElementById('card-reference');
                const currentWidthPx = CARD_WIDTH_MM * pixelsPerMm;
                cardDiv.style.width = `${currentWidthPx}px`;
                document.getElementById('calibration-slider').value = currentWidthPx;
            }
        }
        // Calibration slider listener
        document.getElementById('calibration-slider').addEventListener('input', (e) => {
            const widthPx = e.target.value;
            document.getElementById('card-reference').style.width = `${widthPx}px`;
        });
        function saveCalibration() {
            const finalWidthPx = document.getElementById('calibration-slider').value;
            pixelsPerMm = finalWidthPx / CARD_WIDTH_MM;
            localStorage.setItem('ring_tool_ppm', pixelsPerMm);
            document.getElementById('ppi-debug').innerText = "Calibrated";
            toggleCalibration();
            updateCircleFromSlider(); // Re-render main circle with new math
            showToast("Screen Calibrated Successfully!");
        }
        // Initialize
        document.addEventListener('DOMContentLoaded', init);
